#!/usr/bin/env bash
set -euo pipefail


MODEL="${MODEL:-}"
if [[ -z "$MODEL" ]]; then
  echo "❌ MODEL is not set. Export it before running:" >&2
  echo '   export MODEL="HiDream-ai/HiDream-O1-Image"' >&2
  exit 1
fi

# ---- HELPERS ---------------------------------------------------------------
urlencode() {
  local string="$1" encoded="" i char
  for (( i=0; i<${#string}; i++ )); do
    char="${string:i:1}"
    case "$char" in
      [a-zA-Z0-9._~-]) encoded+="$char" ;;
      *) printf -v encoded '%s%%%02X' "$encoded" "'$char" ;;
    esac
  done
  printf '%s' "$encoded"
}

# Validate the FIBO JSON prompt, fill the ${MODEL_LABEL}/${MODEL_COMPANY} placeholders
# (used by 9A) and compact it to a single line.
# Substitution happens inside jq so the values are JSON-escaped correctly.
fill_prompt() {
  jq -c \
    --arg label   "$MODEL_LABEL"   \
    --arg company "$MODEL_COMPANY" \
    'walk(if type == "string" then
            split("${MODEL_LABEL}")   | join($label) |
            split("${MODEL_COMPANY}") | join($company)
          else . end)' <<<"$1"
}

queue_job() {
  local index="$1"
  local id="$2"
  local prompt="$3"

  if ! prompt="$(fill_prompt "$prompt")"; then
    echo "❌ Prompt $id is not valid JSON — skipping." >&2
    return 1
  fi

  local short task_name
  short="$(jq -r '.short_description // ""' <<<"$prompt")"
  task_name="$(printf '%02d' "$index") ${id} ${short:0:16}"

  printf "[QUEUE %02d %s] %s…\n" "$index" "$id" "${short:0:120}"

  local json
  json=$(jq -n \
    --arg  prompt   "$prompt"   \
    --arg  sampler  "$SAMPLER"  \
    --arg  model    "$MODEL"    \
    --argjson steps  $STEPS     \
    --argjson cfg    $CFG       \
    --argjson ag     $AG        \
    --arg gnm        "$GUIDANCENAME" \
    --argjson gsc    $GUIDANCESCALE \
    --argjson w      $WIDTH     \
    --argjson h      $HEIGHT    \
    --argjson seed   $SEED      \
    '{
      sd_model_checkpoint: $model,
      checkpoint:           $model,
      prompt:       $prompt,
      steps:        $steps,
      cfg_scale:    $cfg,
      cfg_true:     $ag,
      guidance_name: $gnm,
      guidance_scale: $gsc,
      width:        $w,
      height:       $h,
      sampler_name: $sampler,
      seed:         $seed,
      batch_size:   1,
      n_iter:       1,
      save_images:  true
    }')

  curl -s -X POST "$SCHED?name=$(urlencode "$task_name")" \
    -H "Content-Type: application/json" \
    -d "$json" > /dev/null
}

